create table if not exists public.foncier_studies(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id),title text not null,slug text unique,location_label text,surface numeric check(surface>0),terrain_nature text,introduction text,analysis jsonb not null default '{}',scenarios jsonb not null default '[]',status text not null default 'private_draft' check(status in('private_draft','analysis','ready_for_review','private_shared','public_authorized')),publication_authorized_at timestamptz,publication_authorized_by uuid references auth.users(id),share_token_hash text,share_expires_at timestamptz,share_revoked_at timestamptz,is_synthetic boolean not null default false,source_lead_id uuid references public.foncier_land_leads(id) on delete set null);
create table if not exists public.foncier_study_assets(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),study_id uuid not null references public.foncier_studies(id) on delete cascade,kind text not null check(kind in('photo','model_3d','document','render','brochure')),storage_path text not null,original_name text,mime_type text,size_bytes bigint,metadata jsonb not null default '{}');
alter table public.foncier_studies enable row level security;alter table public.foncier_study_assets enable row level security;
create policy "admins manage studies" on public.foncier_studies for all to authenticated using(true) with check(true);
create policy "admins manage study assets" on public.foncier_study_assets for all to authenticated using(true) with check(true);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('foncier-private','foncier-private',false,52428800,array['image/jpeg','image/png','image/webp','application/pdf','model/gltf-binary','model/gltf+json']) on conflict(id) do update set public=false;
create policy "admins read private study files" on storage.objects for select to authenticated using(bucket_id='foncier-private');
create policy "admins upload private study files" on storage.objects for insert to authenticated with check(bucket_id='foncier-private');
create policy "admins update private study files" on storage.objects for update to authenticated using(bucket_id='foncier-private') with check(bucket_id='foncier-private');
create policy "admins delete private study files" on storage.objects for delete to authenticated using(bucket_id='foncier-private');
insert into public.foncier_studies(title,slug,location_label,surface,terrain_nature,introduction,analysis,scenarios,status,is_synthetic) values('Projet HORIZON — Étude foncière conceptuelle','projet-horizon','Territoire insulaire imaginaire',2600,'Terrain polygonal synthétique légèrement en pente','Démonstration publique créée sans aucune donnée immobilière réelle.',jsonb_build_object('altitude_min_fictive_m',18,'altitude_max_fictive_m',26,'denivele_fictif_m',8,'zonage','non applicable'),'[{"id":"townhouses","label":"Townhouses"},{"id":"residential","label":"Résidentiel"},{"id":"commercial","label":"Commercial"},{"id":"mixed","label":"Mixte"}]'::jsonb,'public_authorized',true) on conflict(slug) do nothing;
create index if not exists foncier_studies_status_idx on public.foncier_studies(status,updated_at desc);
